const requesters='A visitor asks someone to|A local keeper wants someone to|A neighbor is looking for someone to|A traveler wants someone to|A regular visitor has asked someone to|A local guide is seeking someone to|A nearby resident needs someone to|A returning visitor would like someone to|A caretaker asks someone to|A messenger brings a request to';
export function placeProfile(observations,activities,goals) {
  return {description:recipe(observations,activities),rumor:recipe(requesters,goals.split('|').map(v=>`${v}.`))};
}
