export function siteProfileFor(place,population) {
  if(place.category==='home')return siteProfiles[population===0?'vacant':'home'];
  const kind=place.type || place.category;
  if(['graveyard','cemetery','necropolis'].includes(kind))return siteProfiles.cemetery;
  if(['tomb','crypt','mausoleum'].includes(kind))return siteProfiles.tomb;
  return siteProfiles[kind] || siteProfiles[place.category];
}
